def build(subj, rows, title):
    qs = []
    for i, (tp, q, opts, c, ex) in enumerate(rows):
        assert c in L[:len(opts)], (subj, i)
        qs.append({'id': 'v91-%s-%d' % (subj, i + 1), 'n': i + 1, 'topic': tp, 'multi': False, 'correct': [c], 'q': q,
                   'opts': [{'l': L[j], 't': t} for j, t in enumerate(opts)],
                   'ex': 'Дұрыс жауап — %s) %s. %s' % (c, opts[L.index(c)], ex)})
    key = 'v91-%s' % subj
    d = {'key': key, 'variant': 91, 'subject': subj, 'lang': 'kz', 'origLang': 'en' if subj == 'english' else 'kz', 'source': 'ai', 'title': title, 'questions': qs}
    open(os.path.join(ROOT, 'data/sets/%s.js' % key), 'w', encoding='utf-8').write('Shyn.addSet(' + json.dumps(d, ensure_ascii=False) + ');\n')
    return key

keys = [build('english', EN, 'Нұсқа 91 · Ағылшын: лексика, шырай, үстеу'),
        build('fundamentals', FU, 'Нұсқа 91 · ОДТ: статистика, ықтималдық, геометрия'),
        build('db', DB, 'Нұсқа 91 · Деректер қоры: индекстер, транзакциялар')]
idx = os.path.join(ROOT, 'data/index.js'); s = open(idx, encoding='utf-8').read()
arr = json.loads(s[s.index('['):s.rindex(']') + 1]); arr = [a for a in arr if not a.startswith('v91-')] + keys
open(idx, 'w', encoding='utf-8').write('Shyn.setFiles(' + json.dumps(arr, ensure_ascii=False) + ');\n')
print('v91', len(DB) + len(EN) + len(FU))
